def _ascii_letter(c):
    return ("A" <= c and c <= "Z") or ("a" <= c and c <= "z")


def _word_bounded(haystack, needle):
    start = 0
    n = len(needle)
    for _ in range(len(haystack) + 1):
        idx = haystack.find(needle, start)
        if idx == -1:
            return False
        before_ok = idx == 0 or not _ascii_letter(haystack[idx - 1])
        after_idx = idx + n
        after_ok = after_idx == len(haystack) or not _ascii_letter(haystack[after_idx])
        if before_ok and after_ok:
            return True
        start = idx + 1
    return False


def transform(row):
    parts = []
    if row["specific_issues"]:
        parts.append(row["specific_issues"])
    if row["issue_codes"]:
        parts.append(row["issue_codes"])
    text = " || ".join(parts).lower()

    found = []
    if "artificial intelligence" in text:
        found.append("artificial intelligence")
    if _word_bounded(text, "ai"):
        found.append("AI")
    if "machine learning" in text:
        found.append("machine learning")
    if (_word_bounded(text, "llm") or _word_bounded(text, "llms")
            or _word_bounded(text, "large language model")
            or _word_bounded(text, "large language models")):
        found.append("large language model")
    if ("deepfake" in text or "deepfakes" in text
            or "deep fake" in text or "deep fakes" in text):
        found.append("deepfake")
    if "algorithmic" in text:
        found.append("algorithmic")

    return dict(row, mentions_ai=bool(found), ai_terms_found="; ".join(found))

