def _is_plain_number(text):
    if text == "":
        return False
    i = 0
    if text[0] == "-" or text[0] == "+":
        i = 1
    if i == len(text):
        return False
    seen_digit = False
    seen_dot = False
    for j in range(i, len(text)):
        c = text[j]
        if "0" <= c and c <= "9":
            seen_digit = True
        elif c == "." and not seen_dot:
            seen_dot = True
        else:
            return False
    return seen_digit


def _read_money(value, field, filing_uuid):
    if value == None:
        return 0.0
    text = str(value).strip()
    if text == "" or text == "None":
        return 0.0
    if not _is_plain_number(text):
        refuse(
            "filing " + filing_uuid + ": " + field + " reads " + repr(text) +
            ", which is not a number. Reading it as zero would enter the " +
            "published totals as if the filing had reported nothing, so " +
            "this is a question for a person."
        )
    amount = float(text)
    if amount < 0:
        refuse(
            "filing " + filing_uuid + ": " + field + " reports " + repr(text) +
            ", a negative amount. Nothing in the filing says whether it is a " +
            "refund, a correction or an error, and counting it, dropping it " +
            "and subtracting it are three different published totals."
        )
    return amount


def transform(row):
    return dict(
        row,
        income_usd=_read_money(row["income"], "income", row["filing_uuid"]),
        expenses_usd=_read_money(row["expenses"], "expenses", row["filing_uuid"]),
    )

def transform(row):
    if row["type"].startswith("Registration"):
        filing_class = "registration"
    elif row["registrant"] == row["client"]:
        filing_class = "in_house"
    else:
        filing_class = "external_paid"
    return dict(row, filing_class=filing_class)
